/* ── SCM_ADM_CMBO_SQL_M — 콤보 SQL(공용) — 없을 때만 · insert · 키 SQL_ID, MDU_DIVS_CD (PK) · 16행 */
INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT S.SQL_ID, S.MDU_DIVS_CD, S.SQL_NM, S.SQL_DTL_CTN, S.USE_YN, 'admin', SYSDATE, 'admin', SYSDATE
  FROM (SELECT 'CELL_PROD_SITE_ID' SQL_ID, 'DM' MDU_DIVS_CD, 'DMF0021 Cell Prod Site 셀 콤보 (div40 Catch_Up)' SQL_NM, 'SELECT SEGMENT1 AS CODE, ATTRIBUTE1 AS NAME' || CHR(10) || 'FROM SCM_ADM_LOOKUP_MASTER_DETAIL' || CHR(10) || 'WHERE LOOKUP_TYPE = ''SP_CELL_PROD_SITE'' AND SEGMENT1 = ''-'' AND VALID_YN = ''Y''' || CHR(10) || '  AND NOT EXISTS (SELECT 1 FROM SCM_ITEM_M_SN I' || CHR(10) || '                   WHERE I.ACTIVE_FLAG = ''Y'' AND I.FORECAST_INFO_BIZ_TYPE = ''CELL''' || CHR(10) || '                     AND I.DIVISION_ID = @divisionId AND I.ITEM_ID = @itemId' || CHR(10) || '                     AND @itemId IS NOT NULL AND @itemId <> ''ALL'')' || CHR(10) || 'UNION ALL' || CHR(10) || 'SELECT DISTINCT S.SCM_SITE_ID AS CODE, M.ATTRIBUTE1 AS NAME' || CHR(10) || 'FROM SCM_MST_SITE S' || CHR(10) || 'JOIN (SELECT DISTINCT I.DIVISION_ID, I.COMPANY_ID, I.SCP_OPERATION_GROUP' || CHR(10) || '        FROM SCM_ITEM_M_SN I' || CHR(10) || '       WHERE I.ACTIVE_FLAG = ''Y'' AND I.ITEM_TYPE IS NOT NULL' || CHR(10) || '         AND I.FORECAST_INFO_BIZ_TYPE = ''CELL''' || CHR(10) || '         AND (@divisionId IS NULL OR I.DIVISION_ID = @divisionId)' || CHR(10) || '         AND (@itemId IS NULL OR @itemId = ''ALL'' OR I.ITEM_ID = @itemId)) SS' || CHR(10) || '  ON S.DIVISION_ID = SS.DIVISION_ID AND S.OPERATION_GROUP = SS.SCP_OPERATION_GROUP' || CHR(10) || ' AND S.COMPANY_ID = SS.COMPANY_ID' || CHR(10) || 'JOIN SCM_ADM_LOOKUP_MASTER_DETAIL M' || CHR(10) || '  ON M.LOOKUP_TYPE = ''SP_CELL_PROD_SITE'' AND M.SEGMENT1 = S.SCM_SITE_ID AND M.VALID_YN = ''Y''' || CHR(10) || 'WHERE S.SITE_TYPE = ''PLANT'' AND S.OPERATION_GROUP = ''A'' AND S.OSP_YN = ''N''' || CHR(10) || '  AND ( @divisionId IS NULL' || CHR(10) || '        OR EXISTS ( SELECT 1' || CHR(10) || '                      FROM SCM_ITEM_M_SN I2' || CHR(10) || '                     WHERE I2.DIVISION_ID = @divisionId' || CHR(10) || '                       AND I2.ITEM_ID = @itemId' || CHR(10) || '                       AND I2.ACTIVE_FLAG = ''Y''' || CHR(10) || '                       AND I2.FORECAST_INFO_BIZ_TYPE = ''CELL'' ) )' SQL_DTL_CTN, 'Y' USE_YN FROM DUAL) S
 WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M T WHERE NVL(TO_CHAR(T.SQL_ID), '~') = NVL(TO_CHAR(S.SQL_ID), '~') AND NVL(TO_CHAR(T.MDU_DIVS_CD), '~') = NVL(TO_CHAR(S.MDU_DIVS_CD), '~'));
INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT S.SQL_ID, S.MDU_DIVS_CD, S.SQL_NM, S.SQL_DTL_CTN, S.USE_YN, 'admin', SYSDATE, 'admin', SYSDATE
  FROM (SELECT 'Division' SQL_ID, 'ALL' MDU_DIVS_CD, 'Division 조회' SQL_NM, 'SELECT DIVISION_ID AS CODE , DIVISION_ID AS NAME FROM SCM_MST_DIVISION WHERE ( @param1 IS NULL OR DIVISION_ID LIKE ''%'' || @param1 || ''%'' ) OR ( @param1 IS NULL OR DIVISION_NAME LIKE ''%'' || @param1 || ''%'' ) GROUP BY DIVISION_ID ORDER BY UPPER(DIVISION_ID)' SQL_DTL_CTN, 'Y' USE_YN FROM DUAL) S
 WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M T WHERE NVL(TO_CHAR(T.SQL_ID), '~') = NVL(TO_CHAR(S.SQL_ID), '~') AND NVL(TO_CHAR(T.MDU_DIVS_CD), '~') = NVL(TO_CHAR(S.MDU_DIVS_CD), '~'));
INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT S.SQL_ID, S.MDU_DIVS_CD, S.SQL_NM, S.SQL_DTL_CTN, S.USE_YN, 'admin', SYSDATE, 'admin', SYSDATE
  FROM (SELECT 'Division_SCP' SQL_ID, 'ALL' MDU_DIVS_CD, '[SCP] AS-IS UP_FX_GetCommonDataList_SCP @Code=''Division''' SQL_NM, 'SELECT A.DIVISION_ID AS CODE , A.DIVISION_ID || '' '' || A.DIVISION_NAME AS NAME , A.DAILY_PLAN_PERIOD , A.VALID_YN , A.CREATION_DATE , A.CREATED_BY , A.LAST_UPDATE_DATE , A.LAST_UPDATED_BY , A.ATTRIBUTE1 , A.ATTRIBUTE2 , A.ATTRIBUTE3 , A.ATTRIBUTE4 , A.ATTRIBUTE5 , A.ATTRIBUTE6 , A.ATTRIBUTE7 , A.ATTRIBUTE8 , A.ATTRIBUTE9 , A.ATTRIBUTE10 FROM SCM_MST_DIVISION A WHERE A.DIVISION_ID IN ( SELECT U.UNIT_ID FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M U WHERE U.UNIT_TP_CD = ''D'' AND U.USE_YN = ''Y'' AND U.USER_ID = @sesUserId AND U.USER_GR_ID IN ( SELECT G.USER_GR_ID FROM SCM_ADM_USER_GR_MPG_M G WHERE G.USER_ID = @sesUserId AND G.USE_YN = ''Y'' ) AND ( NVL(TRIM(@mnuId), ''ALL'') = ''ALL'' OR U.USER_GR_ID IN ( SELECT M.USER_GR_ID FROM SCM_ADM_USER_GR_MNU_MPG_M M WHERE M.MNU_ID = @mnuId AND M.USE_YN = ''Y'' ) ) ) AND A.VALID_YN = ''Y'' ORDER BY UPPER(A.ATTRIBUTE1)' SQL_DTL_CTN, 'Y' USE_YN FROM DUAL) S
 WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M T WHERE NVL(TO_CHAR(T.SQL_ID), '~') = NVL(TO_CHAR(S.SQL_ID), '~') AND NVL(TO_CHAR(T.MDU_DIVS_CD), '~') = NVL(TO_CHAR(S.MDU_DIVS_CD), '~'));
INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT S.SQL_ID, S.MDU_DIVS_CD, S.SQL_NM, S.SQL_DTL_CTN, S.USE_YN, 'admin', SYSDATE, 'admin', SYSDATE
  FROM (SELECT 'Division_SCP_NoEE' SQL_ID, 'ALL' MDU_DIVS_CD, '[SCP0001] Division_SCP + ATTRIBUTE3<>EE (AS-IS GetDivisionWithoutEE 재현)' SQL_NM, 'SELECT A.DIVISION_ID AS CODE , A.DIVISION_ID || '' '' || A.DIVISION_NAME AS NAME , A.DAILY_PLAN_PERIOD , A.VALID_YN , A.CREATION_DATE , A.CREATED_BY , A.LAST_UPDATE_DATE , A.LAST_UPDATED_BY , A.ATTRIBUTE1 , A.ATTRIBUTE2 , A.ATTRIBUTE3 , A.ATTRIBUTE4 , A.ATTRIBUTE5 , A.ATTRIBUTE6 , A.ATTRIBUTE7 , A.ATTRIBUTE8 , A.ATTRIBUTE9 , A.ATTRIBUTE10 FROM SCM_MST_DIVISION A WHERE A.DIVISION_ID IN ( SELECT U.UNIT_ID FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M U WHERE U.UNIT_TP_CD = ''D'' AND U.USE_YN = ''Y'' AND U.USER_ID = @sesUserId AND U.USER_GR_ID IN ( SELECT G.USER_GR_ID FROM SCM_ADM_USER_GR_MPG_M G WHERE G.USER_ID = @sesUserId AND G.USE_YN = ''Y'' ) AND ( NVL(TRIM(@mnuId), ''ALL'') = ''ALL'' OR U.USER_GR_ID IN ( SELECT M.USER_GR_ID FROM SCM_ADM_USER_GR_MNU_MPG_M M WHERE M.MNU_ID = @mnuId AND M.USE_YN = ''Y'' ) ) ) AND A.VALID_YN = ''Y'' AND A.ATTRIBUTE3 <> ''EE'' ORDER BY UPPER(A.ATTRIBUTE1)' SQL_DTL_CTN, 'Y' USE_YN FROM DUAL) S
 WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M T WHERE NVL(TO_CHAR(T.SQL_ID), '~') = NVL(TO_CHAR(S.SQL_ID), '~') AND NVL(TO_CHAR(T.MDU_DIVS_CD), '~') = NVL(TO_CHAR(S.MDU_DIVS_CD), '~'));
INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT S.SQL_ID, S.MDU_DIVS_CD, S.SQL_NM, S.SQL_DTL_CTN, S.USE_YN, 'admin', SYSDATE, 'admin', SYSDATE
  FROM (SELECT 'EndCustomer' SQL_ID, 'DM' MDU_DIVS_CD, 'EndCustomer' SQL_NM, 'SELECT SEGMENT1                    AS DIVISION_ID' || CHR(10) || '     , CAST(NULL AS VARCHAR2(100)) AS DEPT_ID' || CHR(10) || '     , SEGMENT2                    AS CODE' || CHR(10) || '     , SEGMENT3                    AS NAME' || CHR(10) || '  FROM SCM_ADM_LOOKUP_MASTER_DETAIL' || CHR(10) || ' WHERE LOOKUP_TYPE = ''END_CUSTOMER''' || CHR(10) || '   AND VALID_YN    = ''Y''' || CHR(10) || '   AND ( NVL(@divisionId, ''ALL'') = ''ALL''' || CHR(10) || '         OR SEGMENT1 = @divisionId )' || CHR(10) || ' ORDER BY DISPLAY_SEQ' SQL_DTL_CTN, 'Y' USE_YN FROM DUAL) S
 WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M T WHERE NVL(TO_CHAR(T.SQL_ID), '~') = NVL(TO_CHAR(S.SQL_ID), '~') AND NVL(TO_CHAR(T.MDU_DIVS_CD), '~') = NVL(TO_CHAR(S.MDU_DIVS_CD), '~'));
INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT S.SQL_ID, S.MDU_DIVS_CD, S.SQL_NM, S.SQL_DTL_CTN, S.USE_YN, 'admin', SYSDATE, 'admin', SYSDATE
  FROM (SELECT 'FCST_TYPE' SQL_ID, 'DM' MDU_DIVS_CD, '[PJ20209643] W/S 프로세스 -- FCST Type 권한 정리' SQL_NM, 'WITH WT_INPUT AS (' || CHR(13) || CHR(10) || '	SELECT CASE WHEN A.USER_GR_ID = ''DM Planner (W/S)'' AND NVL(@editModeYn,''N'') = ''Y'' THEN ''Y'' ELSE ''N'' END AS EDIT_MODE_YN' || CHR(13) || CHR(10) || '	     , CASE WHEN A.USER_GR_ID = ''DM Planner (W/S)'' THEN ''Y'' ELSE ''N'' END DM_PLAN_WS_YN' || CHR(13) || CHR(10) || '	     , A.USER_GR_ID ' || CHR(13) || CHR(10) || '	     , A.USE_YN ' || CHR(13) || CHR(10) || '	FROM   SCM_ADM_USER_GR_MPG_M A' || CHR(13) || CHR(10) || '	WHERE  A.USER_ID = @sesUserId' || CHR(13) || CHR(10) || '	AND    A.USE_YN = ''Y''' || CHR(13) || CHR(10) || ')' || CHR(13) || CHR(10) || 'SELECT SEGMENT1 AS CODE, SEGMENT2 AS NAME' || CHR(13) || CHR(10) || 'FROM   SCM_ADM_LOOKUP_MASTER_DETAIL A ' || CHR(13) || CHR(10) || 'WHERE  LOOKUP_TYPE = ''SALES_TYPE_CODE2''' || CHR(13) || CHR(10) || 'AND    VALID_YN = ''Y''' || CHR(13) || CHR(10) || 'AND    EXISTS (SELECT 1 ' || CHR(13) || CHR(10) || '               FROM   WT_INPUT' || CHR(13) || CHR(10) || '               WHERE  DM_PLAN_WS_YN = ''Y'')' || CHR(13) || CHR(10) || 'UNION ' || CHR(13) || CHR(10) || 'SELECT SEGMENT1 AS CODE, SEGMENT2 AS NAME' || CHR(13) || CHR(10) || 'FROM   SCM_ADM_LOOKUP_MASTER_DETAIL A ' || CHR(13) || CHR(10) || 'WHERE  LOOKUP_TYPE = ''SALES_TYPE_CODE''' || CHR(13) || CHR(10) || 'AND    NVL(ATTRIBUTE2,''N'') <> ''Y''' || CHR(13) || CHR(10) || 'AND    VALID_YN = ''Y''' || CHR(13) || CHR(10) || 'AND    EXISTS (SELECT 1 ' || CHR(13) || CHR(10) || '               FROM   WT_INPUT' || CHR(13) || CHR(10) || '               WHERE  DM_PLAN_WS_YN = ''N'')' || CHR(13) || CHR(10) || 'UNION' || CHR(13) || CHR(10) || 'SELECT CODE, NAME' || CHR(13) || CHR(10) || 'FROM' || CHR(13) || CHR(10) || '(' || CHR(13) || CHR(10) || '	SELECT SEGMENT1 AS CODE, SEGMENT2 AS NAME' || CHR(13) || CHR(10) || '	FROM   SCM_ADM_LOOKUP_MASTER_DETAIL A ' || CHR(13) || CHR(10) || '	WHERE  LOOKUP_TYPE = ''SALES_TYPE_CODE2''' || CHR(13) || CHR(10) || '	AND    VALID_YN = ''Y''' || CHR(13) || CHR(10) || '	UNION ALL' || CHR(13) || CHR(10) || '	SELECT SEGMENT1 AS CODE, SEGMENT2 AS NAME' || CHR(13) || CHR(10) || '	FROM   SCM_ADM_LOOKUP_MASTER_DETAIL A ' || CHR(13) || CHR(10) || '	WHERE  LOOKUP_TYPE = ''SALES_TYPE_CODE2_ADD''' || CHR(13) || CHR(10) || '	AND    VALID_YN = ''Y''' || CHR(13) || CHR(10) || ') A' || CHR(13) || CHR(10) || 'WHERE EXISTS (SELECT 1 ' || CHR(13) || CHR(10) || '              FROM   WT_INPUT' || CHR(13) || CHR(10) || '              WHERE  EDIT_MODE_YN = ''Y'')' SQL_DTL_CTN, 'Y' USE_YN FROM DUAL) S
 WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M T WHERE NVL(TO_CHAR(T.SQL_ID), '~') = NVL(TO_CHAR(S.SQL_ID), '~') AND NVL(TO_CHAR(T.MDU_DIVS_CD), '~') = NVL(TO_CHAR(S.MDU_DIVS_CD), '~'));
INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT S.SQL_ID, S.MDU_DIVS_CD, S.SQL_NM, S.SQL_DTL_CTN, S.USE_YN, 'admin', SYSDATE, 'admin', SYSDATE
  FROM (SELECT 'FcstType' SQL_ID, 'DM' MDU_DIVS_CD, 'FCST Type by Division' SQL_NM, 'SELECT SEGMENT1 AS CODE, SEGMENT2 AS NAME' || CHR(10) || 'FROM SCM_ADM_LOOKUP_MASTER_DETAIL' || CHR(10) || 'WHERE LOOKUP_TYPE = ''SALES_TYPE_CODE'' AND VALID_YN = ''Y''' || CHR(10) || 'ORDER BY DISPLAY_SEQ' SQL_DTL_CTN, 'Y' USE_YN FROM DUAL) S
 WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M T WHERE NVL(TO_CHAR(T.SQL_ID), '~') = NVL(TO_CHAR(S.SQL_ID), '~') AND NVL(TO_CHAR(T.MDU_DIVS_CD), '~') = NVL(TO_CHAR(S.MDU_DIVS_CD), '~'));
INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT S.SQL_ID, S.MDU_DIVS_CD, S.SQL_NM, S.SQL_DTL_CTN, S.USE_YN, 'admin', SYSDATE, 'admin', SYSDATE
  FROM (SELECT 'Incoterms' SQL_ID, 'ALL' MDU_DIVS_CD, 'Incoterms 조회' SQL_NM, 'SELECT SEGMENT1 AS CODE, SEGMENT2 AS NAME FROM SCM_ADM_LOOKUP_MASTER_DETAIL WHERE LOOKUP_TYPE = ''INCOTERMS'' AND VALID_YN = ''Y'' ORDER BY DISPLAY_SEQ' SQL_DTL_CTN, 'Y' USE_YN FROM DUAL) S
 WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M T WHERE NVL(TO_CHAR(T.SQL_ID), '~') = NVL(TO_CHAR(S.SQL_ID), '~') AND NVL(TO_CHAR(T.MDU_DIVS_CD), '~') = NVL(TO_CHAR(S.MDU_DIVS_CD), '~'));
INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT S.SQL_ID, S.MDU_DIVS_CD, S.SQL_NM, S.SQL_DTL_CTN, S.USE_YN, 'admin', SYSDATE, 'admin', SYSDATE
  FROM (SELECT 'Location' SQL_ID, 'ALL' MDU_DIVS_CD, '[공통] AS-IS UP_FX_GetCommonDataList @Code=''Location''' SQL_NM, 'SELECT B.SEGMENT1 CODE, B.SEGMENT2 NAME FROM SCM_ADM_LOOKUP_MASTER A INNER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL B ON A.LOOKUP_TYPE = B.LOOKUP_TYPE WHERE A.LOOKUP_TYPE = ''LOCATION_GROUP'' AND (@segment1 IS NULL OR B.SEGMENT3 = @segment1) ORDER BY B.DISPLAY_SEQ' SQL_DTL_CTN, 'Y' USE_YN FROM DUAL) S
 WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M T WHERE NVL(TO_CHAR(T.SQL_ID), '~') = NVL(TO_CHAR(S.SQL_ID), '~') AND NVL(TO_CHAR(T.MDU_DIVS_CD), '~') = NVL(TO_CHAR(S.MDU_DIVS_CD), '~'));
INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT S.SQL_ID, S.MDU_DIVS_CD, S.SQL_NM, S.SQL_DTL_CTN, S.USE_YN, 'admin', SYSDATE, 'admin', SYSDATE
  FROM (SELECT 'OPMZ_DATE_WEEKLY_SCP_ALL' SQL_ID, 'ALL' MDU_DIVS_CD, '[SCP_ALL] AS-IS UP_FX_GetCommonDataList_SCP_ALL @Code=''OPMZ_DATE_WEEKLY''' SQL_NM, 'SELECT A.PLAN_NAME AS CODE , CASE WHEN FP_TARGET_YN = ''Y'' THEN TO_CHAR(FN_CHAR_TO_DATE(A.PLAN_NAME), ''YYYY-MM-DD'') || '' ('' || B.WEEK_NAME || '')'' ELSE TO_CHAR(FN_CHAR_TO_DATE(A.PLAN_NAME), ''YYYY-MM-DD'') || '' ('' || B.WEEK_NAME || '')'' || '' (No Plan)'' END name , A.DIVISION_ID FROM SCM_MST_PLAN A INNER JOIN SCM_SYS_CALENDAR_M B ON A.PLAN_NAME = B.BASIS_YYYYMMDD LEFT JOIN ( SELECT DIVISION_ID , PLAN_START_YYYYMMDD , FP_TARGET_YN , MRP_TARGET_YN , DM_RTF_YN FROM SCP_PLN_INTERFACE_YN WHERE 1=1 ) C ON A.PLAN_NAME = C.PLAN_START_YYYYMMDD AND A.DIVISION_ID = C.DIVISION_ID WHERE 1=1 AND A.plan_cycle = ''WEEKLY'' AND A.plan_name >= FN_GET_BUCKET_YYYYMMDD(-24) ORDER BY UPPER(A.PLAN_NAME) DESC' SQL_DTL_CTN, 'Y' USE_YN FROM DUAL) S
 WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M T WHERE NVL(TO_CHAR(T.SQL_ID), '~') = NVL(TO_CHAR(S.SQL_ID), '~') AND NVL(TO_CHAR(T.MDU_DIVS_CD), '~') = NVL(TO_CHAR(S.MDU_DIVS_CD), '~'));
INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT S.SQL_ID, S.MDU_DIVS_CD, S.SQL_NM, S.SQL_DTL_CTN, S.USE_YN, 'admin', SYSDATE, 'admin', SYSDATE
  FROM (SELECT 'Plant' SQL_ID, 'ALL' MDU_DIVS_CD, '[공통] AS-IS UP_FX_GetCommonDataList @Code=''Plant''' SQL_NM, 'SELECT distinct S.PLANT_ID AS CODE , MAX((CASE WHEN A.PLANT_NAME IS NULL THEN V.VENDOR_NAME ELSE A.PLANT_NAME END )) AS NAME FROM SCM_MST_SITE S LEFT OUTER JOIN SCM_MST_PLANT_SN A ON A.DIVISION_ID = S.DIVISION_ID AND A.PLANT_ID = S.PLANT_ID LEFT OUTER JOIN SCM_MST_VENDOR V ON V.VENDOR_CODE = S.PLANT_ID WHERE (@divisionId IS NULL OR S.DIVISION_ID = @divisionId) AND ( (@plantId IS NULL OR S.PLANT_ID LIKE ''%'' || @plantId || ''%'') OR (@plantId IS NULL OR PLANT_NAME LIKE ''%'' || @plantId || ''%'') ) AND S.VALID_YN =''Y'' GROUP BY S.PLANT_ID ORDER BY UPPER(S.PLANT_ID)' SQL_DTL_CTN, 'Y' USE_YN FROM DUAL) S
 WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M T WHERE NVL(TO_CHAR(T.SQL_ID), '~') = NVL(TO_CHAR(S.SQL_ID), '~') AND NVL(TO_CHAR(T.MDU_DIVS_CD), '~') = NVL(TO_CHAR(S.MDU_DIVS_CD), '~'));
INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT S.SQL_ID, S.MDU_DIVS_CD, S.SQL_NM, S.SQL_DTL_CTN, S.USE_YN, 'admin', SYSDATE, 'admin', SYSDATE
  FROM (SELECT 'PlantSite' SQL_ID, 'DM' MDU_DIVS_CD, '사업부 → 팀 → End Customer → Plant Site' SQL_NM, 'SELECT DIVISION_CODE, DIVISION_CODE || '' '' || DIVISION_NAME AS DIVISION_NAME, TEAM_CODE, TEAM_NAME, END_CUSTOMER_CODE, END_CUSTOMER_NAME, PLANT_SITE_CODE, PLANT_SITE_NAME, CODE, NAME FROM ( SELECT X1.*, PLANT_SITE_CODE AS CODE, PLANT_SITE_NAME AS NAME FROM ( SELECT DIVISION_CODE, DIVISION_NAME, TEAM_CODE, TEAM_NAME, END_CUSTOMER_CODE, END_CUSTOMER_NAME, CODE PLANT_SITE_CODE, NAME PLANT_SITE_NAME FROM (WITH AXIS AS ( SELECT M.DIVISION_ID FROM ( SELECT DIVISION_ID, COUNT(DISTINCT SCM_SITE_ID) N FROM SCM_MST_SITE WHERE SITE_TYPE = ''PLANT'' AND VALID_YN = ''Y'' GROUP BY DIVISION_ID) M JOIN ( SELECT DIVISION_ID, COUNT(DISTINCT PLANT_SITE_ID) N FROM DM_PLN_MKT_FCST WHERE PLANT_SITE_ID IS NOT NULL AND PLANT_SITE_ID <> ''-'' GROUP BY DIVISION_ID) F ON M.DIVISION_ID = F.DIVISION_ID WHERE F.N >= M.N * 0.5), ITM AS ( SELECT DISTINCT DIVISION_ID, SCM_SITE_ID, DEPT_ID FROM SCM_MST_SITE_ITEM WHERE VALID_YN = ''Y'' AND DEPT_ID IS NOT NULL) SELECT DIVISION_CODE, ( SELECT MIN(V.DIVISION_NAME) FROM SCM_MST_DIVISION V WHERE V.DIVISION_ID = X.DIVISION_CODE) AS DIVISION_NAME, TEAM_CODE, ( SELECT CASE @sesLangCd WHEN ''EN'' THEN D.DEPT_NAME_EN WHEN ''CN'' THEN D.DEPT_NAME_CN ELSE D.DEPT_NAME_KO END FROM SCM_MST_SSO_DEPT_INFO D WHERE D.DEPT_ID = X.TEAM_CODE) AS TEAM_NAME, END_CUSTOMER_CODE, NVL((SELECT MIN(L.SEGMENT3) FROM SCM_ADM_LOOKUP_MASTER_DETAIL L WHERE L.LOOKUP_TYPE = ''END_CUSTOMER'' AND L.VALID_YN = ''Y'' AND L.SEGMENT1 = X.DIVISION_CODE AND L.SEGMENT2 = X.END_CUSTOMER_CODE), X.END_CUSTOMER_CODE) AS END_CUSTOMER_NAME, CODE, NAME FROM ( SELECT DISTINCT F.DIVISION_ID AS DIVISION_CODE, I.DEPT_ID AS TEAM_CODE, NVL(S.END_CUSTOMER, F.PROJECT_CODE) AS END_CUSTOMER_CODE, F.PLANT_SITE_ID AS CODE, F.PLANT_SITE_ID AS NAME FROM DM_PLN_MKT_FCST F JOIN AXIS Z ON F.DIVISION_ID = Z.DIVISION_ID LEFT JOIN SCM_MST_SITE S ON F.DIVISION_ID = S.DIVISION_ID AND F.SCM_SITE_ID = S.SCM_SITE_ID LEFT JOIN ITM I ON F.DIVISION_ID = I.DIVISION_ID AND F.SCM_SITE_ID = I.SCM_SITE_ID WHERE F.PLANT_SITE_ID IS NOT NULL AND F.PLANT_SITE_ID <> ''-'' AND F.DIVISION_ID IN ( SELECT UNIT_ID FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M WHERE USER_ID = @sesUserId AND UNIT_TP_CD = ''D'' AND USE_YN = ''Y'') UNION ALL SELECT DISTINCT A.DIVISION_ID, CAST(NULL AS VARCHAR2(200)), CAST(NULL AS VARCHAR2(100)), A.SCM_SITE_ID, A.SCM_SITE_ID FROM SCM_MST_SITE A WHERE A.SITE_TYPE = ''PLANT'' AND A.VALID_YN = ''Y'' AND A.DIVISION_ID NOT IN ( SELECT DIVISION_ID FROM AXIS) AND A.DIVISION_ID IN ( SELECT UNIT_ID FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M WHERE USER_ID = @sesUserId AND UNIT_TP_CD = ''D'' AND USE_YN = ''Y'') ) X ORDER BY UPPER(DIVISION_CODE), UPPER(CODE)) X9 WHERE X9.DIVISION_CODE NOT IN ( SELECT V9.DIVISION_ID FROM SCM_MST_DIVISION V9 WHERE V9.ATTRIBUTE3 = ''EE'') ) X1 ) X3' SQL_DTL_CTN, 'Y' USE_YN FROM DUAL) S
 WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M T WHERE NVL(TO_CHAR(T.SQL_ID), '~') = NVL(TO_CHAR(S.SQL_ID), '~') AND NVL(TO_CHAR(T.MDU_DIVS_CD), '~') = NVL(TO_CHAR(S.MDU_DIVS_CD), '~'));
INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT S.SQL_ID, S.MDU_DIVS_CD, S.SQL_NM, S.SQL_DTL_CTN, S.USE_YN, 'admin', SYSDATE, 'admin', SYSDATE
  FROM (SELECT 'SYSTEM' SQL_ID, 'ALL' MDU_DIVS_CD, 'Lookup System' SQL_NM, '    SELECT  T1.SEGMENT1 CODE, T1.SEGMENT2 NAME' || CHR(13) || CHR(10) || '     FROM  SCM_ADM_LOOKUP_MASTER_DETAIL T1' || CHR(13) || CHR(10) || '    WHERE  1=1' || CHR(13) || CHR(10) || '      AND  T1.LOOKUP_TYPE = ''SYSTEM''' || CHR(13) || CHR(10) || '      AND  T1.VALID_YN = ''Y''' || CHR(13) || CHR(10) || ' ORDER BY  T1.DISPLAY_SEQ' SQL_DTL_CTN, 'Y' USE_YN FROM DUAL) S
 WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M T WHERE NVL(TO_CHAR(T.SQL_ID), '~') = NVL(TO_CHAR(S.SQL_ID), '~') AND NVL(TO_CHAR(T.MDU_DIVS_CD), '~') = NVL(TO_CHAR(S.MDU_DIVS_CD), '~'));
INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT S.SQL_ID, S.MDU_DIVS_CD, S.SQL_NM, S.SQL_DTL_CTN, S.USE_YN, 'admin', SYSDATE, 'admin', SYSDATE
  FROM (SELECT 'SalesSite' SQL_ID, 'DM' MDU_DIVS_CD, '사업부 → 팀 → End Customer → Sales Site' SQL_NM, 'SELECT DIVISION_CODE, DIVISION_CODE || '' '' || DIVISION_NAME AS DIVISION_NAME, TEAM_CODE, TEAM_NAME, END_CUSTOMER_CODE, END_CUSTOMER_NAME, SALES_SITE_CODE, SALES_SITE_NAME, SRC_TYPE, SORT_ORDER, CODE, NAME FROM ( SELECT X1.*, SALES_SITE_CODE AS CODE, SALES_SITE_NAME AS NAME FROM ( SELECT V.DIVISION_ID AS DIVISION_CODE, V.DIVISION_NAME AS DIVISION_NAME, X.DEPT_ID AS TEAM_CODE, ( SELECT CASE @sesLangCd WHEN ''EN'' THEN D9.DEPT_NAME_EN WHEN ''CN'' THEN D9.DEPT_NAME_CN ELSE D9.DEPT_NAME_KO END FROM SCM_MST_SSO_DEPT_INFO D9 WHERE D9.DEPT_ID = X.DEPT_ID) AS TEAM_NAME, X.END_CUSTOMER AS END_CUSTOMER_CODE, NVL((SELECT MIN(L9.SEGMENT3) FROM SCM_ADM_LOOKUP_MASTER_DETAIL L9 WHERE L9.LOOKUP_TYPE = ''END_CUSTOMER'' AND L9.VALID_YN = ''Y'' AND L9.SEGMENT1 = X.DIVISION_ID AND L9.SEGMENT2 = X.END_CUSTOMER), X.END_CUSTOMER) AS END_CUSTOMER_NAME, X.SALES_SITE AS SALES_SITE_CODE, X.SALES_SITE_NAME AS SALES_SITE_NAME, X.SRC_TYPE, X.SORT_ORDER FROM SCM_MST_DIVISION V JOIN ( SELECT DISTINCT A.DIVISION_ID, B.DEPT_ID , CASE WHEN A.DIVISION_ID <> ''40'' THEN A.END_CUSTOMER ELSE B.PROJECT_CODE END AS END_CUSTOMER, A.SCM_SITE_ID AS SALES_SITE, NVL(NULLIF(TRIM(A.SITE_DESCRIPTION), ''-''), A.SCM_SITE_ID) AS SALES_SITE_NAME, ''SITE'' AS SRC_TYPE, 2 AS SORT_ORDER FROM SCM_MST_SITE A LEFT JOIN SCM_MST_SITE_ITEM B ON A.DIVISION_ID = B.DIVISION_ID AND A.SCM_SITE_ID = B.SCM_SITE_ID WHERE A.SITE_TYPE = ''SALES'' AND A.VALID_YN = ''Y'' UNION ALL SELECT DISTINCT L.SEGMENT3, NULL, NULL, L.SEGMENT1, L.SEGMENT2, ''AS'', 1 FROM SCM_ADM_LOOKUP_MASTER_DETAIL L WHERE L.LOOKUP_TYPE = ''AS_SITE_PLANT'' AND L.VALID_YN = ''Y'' ) X ON V.DIVISION_ID = X.DIVISION_ID WHERE V.ATTRIBUTE3 <> ''EE'' AND V.VALID_YN = ''Y'' AND V.DIVISION_ID IN ( SELECT UNIT_ID FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M WHERE USER_ID = @sesUserId AND UNIT_TP_CD = ''D'' AND USE_YN = ''Y'') ORDER BY UPPER(V.DIVISION_ID), X.SORT_ORDER, UPPER(X.DEPT_ID), UPPER(X.END_CUSTOMER), UPPER(X.SALES_SITE) ) X1 ) X3' SQL_DTL_CTN, 'Y' USE_YN FROM DUAL) S
 WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M T WHERE NVL(TO_CHAR(T.SQL_ID), '~') = NVL(TO_CHAR(S.SQL_ID), '~') AND NVL(TO_CHAR(T.MDU_DIVS_CD), '~') = NVL(TO_CHAR(S.MDU_DIVS_CD), '~'));
INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT S.SQL_ID, S.MDU_DIVS_CD, S.SQL_NM, S.SQL_DTL_CTN, S.USE_YN, 'admin', SYSDATE, 'admin', SYSDATE
  FROM (SELECT 'ScmSite' SQL_ID, 'ALL' MDU_DIVS_CD, '[SCP] SCP0127_GET_SEARCH_INFO 2踰덉㎏ 紐⑸줉 (?ъ씠??' SQL_NM, 'SELECT IA.DIVISION_ID' || CHR(10) || '     , IA.CODE' || CHR(10) || '     , IA.NAME' || CHR(10) || '  FROM (SELECT DISTINCT A.DIVISION_ID' || CHR(10) || '             , A.SCM_SITE_ID                    AS CODE' || CHR(10) || '             , A.SCM_SITE_ID                    AS NAME' || CHR(10) || '             , A.SITE_TYPE' || CHR(10) || '          FROM SCM_MST_SITE A' || CHR(10) || '         WHERE A.SITE_TYPE   = ''SALES''' || CHR(10) || '           AND A.DIVISION_ID <> ''40''' || CHR(10) || '           AND A.VALID_YN    = ''Y''' || CHR(10) || '        UNION ALL' || CHR(10) || '        SELECT DISTINCT A.DIVISION_ID' || CHR(10) || '             , A.SCM_SITE_ID                    AS CODE' || CHR(10) || '             , A.SCM_SITE_ID                    AS NAME' || CHR(10) || '             , A.SITE_TYPE' || CHR(10) || '          FROM SCM_MST_SITE       A' || CHR(10) || '             , SCM_MST_SITE_ITEM  B' || CHR(10) || '         WHERE B.DIVISION_ID(+) = A.DIVISION_ID' || CHR(10) || '           AND B.SCM_SITE_ID(+) = A.SCM_SITE_ID' || CHR(10) || '           AND A.SITE_TYPE      = ''SALES''' || CHR(10) || '           AND A.DIVISION_ID    = ''40''' || CHR(10) || '           AND A.VALID_YN       = ''Y''' || CHR(10) || '        UNION ALL' || CHR(10) || '        SELECT DISTINCT A.DIVISION_ID' || CHR(10) || '             , A.SCM_SITE_ID                    AS CODE' || CHR(10) || '             , A.SCM_SITE_ID                    AS NAME' || CHR(10) || '             , A.SITE_TYPE' || CHR(10) || '          FROM SCM_MST_SITE A' || CHR(10) || '         WHERE A.SITE_TYPE = ''PLANT'') IA' || CHR(10) || ' ORDER BY FN_ASIS_SORT_KEY(IA.SITE_TYPE) NULLS FIRST' || CHR(10) || '        , FN_ASIS_SORT_KEY(IA.NAME)      NULLS FIRST' SQL_DTL_CTN, 'Y' USE_YN FROM DUAL) S
 WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M T WHERE NVL(TO_CHAR(T.SQL_ID), '~') = NVL(TO_CHAR(S.SQL_ID), '~') AND NVL(TO_CHAR(T.MDU_DIVS_CD), '~') = NVL(TO_CHAR(S.MDU_DIVS_CD), '~'));
INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT S.SQL_ID, S.MDU_DIVS_CD, S.SQL_NM, S.SQL_DTL_CTN, S.USE_YN, 'admin', SYSDATE, 'admin', SYSDATE
  FROM (SELECT 'YesOrNo' SQL_ID, 'ALL' MDU_DIVS_CD, 'YesOrNo' SQL_NM, 'SELECT ''Y'' AS CODE, ''Y'' AS NAME FROM DUAL UNION ALL SELECT ''N'' AS CODE, ''N'' AS NAME FROM DUAL' SQL_DTL_CTN, 'Y' USE_YN FROM DUAL) S
 WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M T WHERE NVL(TO_CHAR(T.SQL_ID), '~') = NVL(TO_CHAR(S.SQL_ID), '~') AND NVL(TO_CHAR(T.MDU_DIVS_CD), '~') = NVL(TO_CHAR(S.MDU_DIVS_CD), '~'));

COMMIT;
